import 'dart:math' as math;
import 'package:flutter/material.dart';

class Orbit extends StatefulWidget {
  const Orbit({super.key});
  @override
  State<Orbit> createState() => _OrbitState();
}

class _OrbitState extends State<Orbit> with SingleTickerProviderStateMixin {
  late final AnimationController controller;

  @override
  void initState() {
    super.initState();
    controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 3),
    )..repeat();
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: controller,
    child: const Icon(Icons.auto_awesome),
    builder: (context, child) => Transform.rotate(
      angle: controller.value * math.pi * 2,
      child: child,
    ),
  );
}

import 'package:flutter/material.dart';

class DocumentList extends StatelessWidget {
  final Future<List<String>> documents;
  const DocumentList({super.key, required this.documents});

  @override
  Widget build(BuildContext context) => FutureBuilder<List<String>>(
    future: documents,
    builder: (context, snapshot) {
      if (snapshot.connectionState != ConnectionState.done) {
        return const Center(child: CircularProgressIndicator());
      }
      if (snapshot.hasError) {
        return const Text('Unable to load documents');
      }
      final items = snapshot.data ?? <String>[];
      return ListView.builder(
        itemCount: items.length,
        itemBuilder: (context, index) => ListTile(
          key: ValueKey(items[index]),
          title: Text(items[index]),
        ),
      );
    },
  );
}

import 'package:flutter/material.dart';

class NameForm extends StatefulWidget {
  const NameForm({super.key});
  @override
  State<NameForm> createState() => _NameFormState();
}

class _NameFormState extends State<NameForm> {
  final formKey = GlobalKey<FormState>();
  final controller = TextEditingController();

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  void submit() {
    if (!(formKey.currentState?.validate() ?? false)) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Saved: ${controller.text}')),
    );
  }

  @override
  Widget build(BuildContext context) => Form(
    key: formKey,
    child: Column(children: [
      TextFormField(
        controller: controller,
        decoration: const InputDecoration(labelText: 'Document name'),
        validator: (value) =>
            value == null || value.trim().isEmpty ? 'Enter a name' : null,
      ),
      FilledButton(onPressed: submit, child: const Text('Save')),
    ]),
  );
}

import 'package:flutter/material.dart';

void main() => runApp(const DocumentsApp());

class DocumentsApp extends StatelessWidget {
  const DocumentsApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      theme: ThemeData(colorSchemeSeed: Colors.indigo),
      home: Scaffold(
        appBar: AppBar(title: const Text('Virgo Documents')),
        body: const Center(child: DocumentCard(title: 'Getting started')),
      ),
    );
  }
}

class DocumentCard extends StatelessWidget {
  final String title;
  const DocumentCard({super.key, required this.title});

  @override
  Widget build(BuildContext context) => Card(
    child: Padding(
      padding: const EdgeInsets.all(24),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(Icons.description_outlined),
          const SizedBox(height: 12),
          Text(title, style: Theme.of(context).textTheme.titleLarge),
        ],
      ),
    ),
  );
}

import 'package:flutter/material.dart';

class CounterScope extends InheritedNotifier<ValueNotifier<int>> {
  const CounterScope({
    super.key,
    required ValueNotifier<int> counter,
    required super.child,
  }) : super(notifier: counter);

  static ValueNotifier<int> of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<CounterScope>()!.notifier!;
}

class CounterControls extends StatelessWidget {
  const CounterControls({super.key});

  @override
  Widget build(BuildContext context) {
    final counter = CounterScope.of(context);
    return ValueListenableBuilder<int>(
      valueListenable: counter,
      builder: (context, value, child) => Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Count: $value'),
          IconButton(
            onPressed: () => counter.value++,
            icon: const Icon(Icons.add),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';

class SearchResults extends StatelessWidget {
  final List<({String id, String title})> items;
  final bool loading;
  const SearchResults({super.key, required this.items, this.loading = false});

  @override
  Widget build(BuildContext context) => CustomScrollView(
    slivers: [
      const SliverAppBar(title: Text('Documents'), floating: true),
      if (loading)
        const SliverToBoxAdapter(child: LinearProgressIndicator()),
      SliverList.builder(
        itemCount: items.length,
        itemBuilder: (context, index) {
          final (:id, :title) = items[index];
          return ListTile(
            key: ValueKey(id),
            leading: const Icon(Icons.description),
            title: Text(title),
          );
        },
      ),
    ],
  );
}

import 'package:flutter/material.dart';

Future<void> openDocument(BuildContext context, String title) async {
  final saved = await Navigator.of(context).push<bool>(
    MaterialPageRoute(
      builder: (context) => DocumentPage(title: title),
    ),
  );
  if (!context.mounted) return;
  if (saved == true) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Document saved')),
    );
  }
}

class DocumentPage extends StatelessWidget {
  final String title;
  const DocumentPage({super.key, required this.title});

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: Text(title)),
    body: Center(
      child: FilledButton(
        onPressed: () => Navigator.of(context).pop(true),
        child: const Text('Save and return'),
      ),
    ),
  );
}

import 'package:flutter/material.dart';

class Counter extends StatefulWidget {
  final int initial;
  const Counter({super.key, this.initial = 0});

  @override
  State<Counter> createState() => _CounterState();
}

class _CounterState extends State<Counter> {
  late int count;

  @override
  void initState() {
    super.initState();
    count = widget.initial;
  }

  void increment() => setState(() => count++);

  @override
  Widget build(BuildContext context) => Row(
    mainAxisSize: MainAxisSize.min,
    children: [
      Text('Count: $count'),
      IconButton(onPressed: increment, icon: const Icon(Icons.add)),
    ],
  );
}
